# ANI binding library: the only entry consumed by the ArkTS runtime is
# ANI_Constructor (generated by ani_rs::ani_constructor!, #[no_mangle]).
# rust_metadata_* stays exported so rustc can read crate metadata when a
# future Rust crate is compiled against this dylib.

{
  global:
    ANI_Constructor;
    rust_metadata*;
  local:
    *;
};
